// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title DonationContract
 * @dev Смарт-контракт для благотворительного фонда "Внимание"
 * 
 * Основные возможности:
 * - Пожертвования на конкретные проекты
 * - Отслеживание собранных средств по каждому проекту
 * - Хранение истории пожертвований
 * - Возможность вывода средств владельцем контракта
 */
contract DonationContract {
    // Владелец контракта (адрес фонда)
    address public owner;
    
    // Структура проекта
    struct Project {
        uint256 id;                    // Уникальный ID проекта
        string name;                   // Название проекта
        uint256 targetAmount;          // Целевая сумма для сбора (в wei)
        uint256 collectedAmount;       // Собранная сумма (в wei)
        bool isActive;                 // Активен ли проект
        address projectWallet;         // Кошелек проекта (для вывода средств)
    }
    
    // Структура пожертвования
    struct Donation {
        address donor;                 // Адрес донора
        uint256 projectId;             // ID проекта
        uint256 amount;                // Сумма пожертвования (в wei)
        uint256 timestamp;             // Время пожертвования
        bool isAnonymous;              // Анонимное пожертвование или нет
    }
    
    // Маппинг проектов по ID
    mapping(uint256 => Project) public projects;
    
    // Маппинг для хранения всех пожертвований (индекс => Donation)
    mapping(uint256 => Donation) public donations;
    
    // Счетчик пожертвований
    uint256 public donationCount;
    
    // Счетчик проектов
    uint256 public projectCount;
    
    // Маппинг общей суммы пожертвований от каждого донора
    mapping(address => uint256) public donorTotalAmount;
    
    // События для отслеживания действий
    event ProjectCreated(uint256 indexed projectId, string name, uint256 targetAmount);
    event DonationReceived(
        address indexed donor,
        uint256 indexed projectId,
        uint256 amount,
        uint256 timestamp
    );
    event FundsWithdrawn(uint256 indexed projectId, uint256 amount);
    event ProjectStatusChanged(uint256 indexed projectId, bool isActive);
    
    // Модификатор для проверки, что вызывающий является владельцем
    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner can call this function");
        _;
    }
    
    // Конструктор - устанавливает владельца контракта
    constructor() {
        owner = msg.sender;
    }
    
    /**
     * @dev Создание нового проекта
     * @param _name Название проекта
     * @param _targetAmount Целевая сумма для сбора (в wei)
     * @param _projectWallet Кошелек проекта
     */
    function createProject(
        string memory _name,
        uint256 _targetAmount,
        address _projectWallet
    ) public onlyOwner {
        projectCount++;
        
        projects[projectCount] = Project({
            id: projectCount,
            name: _name,
            targetAmount: _targetAmount,
            collectedAmount: 0,
            isActive: true,
            projectWallet: _projectWallet
        });
        
        emit ProjectCreated(projectCount, _name, _targetAmount);
    }
    
    /**
     * @dev Пожертвование на проект
     * @param _projectId ID проекта
     * @param _isAnonymous Анонимное пожертвование или нет
     */
    function donate(uint256 _projectId, bool _isAnonymous) public payable {
        // Проверяем, что проект существует
        require(_projectId > 0 && _projectId <= projectCount, "Project does not exist");
        
        // Проверяем, что проект активен
        require(projects[_projectId].isActive, "Project is not active");
        
        // Проверяем, что сумма больше нуля
        require(msg.value > 0, "Donation amount must be greater than 0");
        
        // Обновляем собранную сумму проекта
        projects[_projectId].collectedAmount += msg.value;
        
        // Обновляем общую сумму пожертвований донора
        donorTotalAmount[msg.sender] += msg.value;
        
        // Создаем запись о пожертвовании
        donationCount++;
        donations[donationCount] = Donation({
            donor: msg.sender,
            projectId: _projectId,
            amount: msg.value,
            timestamp: block.timestamp,
            isAnonymous: _isAnonymous
        });
        
        emit DonationReceived(msg.sender, _projectId, msg.value, block.timestamp);
    }
    
    /**
     * @dev Получить информацию о проекте
     * @param _projectId ID проекта
     */
    function getProject(uint256 _projectId) public view returns (
        uint256 id,
        string memory name,
        uint256 targetAmount,
        uint256 collectedAmount,
        bool isActive,
        address projectWallet
    ) {
        require(_projectId > 0 && _projectId <= projectCount, "Project does not exist");
        Project memory project = projects[_projectId];
        return (
            project.id,
            project.name,
            project.targetAmount,
            project.collectedAmount,
            project.isActive,
            project.projectWallet
        );
    }
    
    /**
     * @dev Получить информацию о пожертвовании
     * @param _donationId ID пожертвования
     */
    function getDonation(uint256 _donationId) public view returns (
        address donor,
        uint256 projectId,
        uint256 amount,
        uint256 timestamp,
        bool isAnonymous
    ) {
        require(_donationId > 0 && _donationId <= donationCount, "Donation does not exist");
        Donation memory donation = donations[_donationId];
        return (
            donation.donor,
            donation.projectId,
            donation.amount,
            donation.timestamp,
            donation.isAnonymous
        );
    }
    
    /**
     * @dev Вывод средств для проекта
     * @param _projectId ID проекта
     * @param _amount Сумма для вывода (в wei)
     */
    function withdrawFunds(uint256 _projectId, uint256 _amount) public onlyOwner {
        require(_projectId > 0 && _projectId <= projectCount, "Project does not exist");
        require(_amount > 0, "Amount must be greater than 0");
        require(projects[_projectId].collectedAmount >= _amount, "Insufficient funds");
        
        address projectWallet = projects[_projectId].projectWallet;
        require(projectWallet != address(0), "Project wallet not set");
        
        // Обновляем баланс проекта
        projects[_projectId].collectedAmount -= _amount;
        
        // Отправляем средства на кошелек проекта
        (bool success, ) = projectWallet.call{value: _amount}("");
        require(success, "Transfer failed");
        
        emit FundsWithdrawn(_projectId, _amount);
    }
    
    /**
     * @dev Изменить статус проекта (активен/неактивен)
     * @param _projectId ID проекта
     * @param _isActive Новый статус
     */
    function setProjectStatus(uint256 _projectId, bool _isActive) public onlyOwner {
        require(_projectId > 0 && _projectId <= projectCount, "Project does not exist");
        projects[_projectId].isActive = _isActive;
        emit ProjectStatusChanged(_projectId, _isActive);
    }
    
    /**
     * @dev Получить общий баланс контракта
     */
    function getContractBalance() public view returns (uint256) {
        return address(this).balance;
    }
    
    /**
     * @dev Получить процент заполнения проекта (0-100)
     * @param _projectId ID проекта
     */
    function getProjectProgress(uint256 _projectId) public view returns (uint256) {
        require(_projectId > 0 && _projectId <= projectCount, "Project does not exist");
        Project memory project = projects[_projectId];
        
        if (project.targetAmount == 0) {
            return 0;
        }
        
        // Возвращаем процент (умножаем на 100 для получения процентов)
        return (project.collectedAmount * 100) / project.targetAmount;
    }
}

